1	import { redirect } from "next/navigation";
2	import type { Role, User } from "@prisma/client";
3	import { db } from "./db";
4	import { realUser } from "./auth";
5	import { canAccess, isStaff, type Area } from "./rbac";
6	
7	/**
8	 * Per-employee (Role.EMPLOYEE) tool grants, layered ADDITIVELY on top of
9	 * lib/rbac.ts's role→area system — nothing in lib/rbac.ts changes behavior
10	 * for CUSTOMER/SUPPORT/BILLING/ADMIN. `canAccess`/`requireArea` there are
11	 * untouched; every one of their ~115 existing call sites is unaffected.
12	 *
13	 * EMPLOYEE is never listed in AREA_ROLES for any area (see lib/rbac.ts), so
14	 * an EMPLOYEE has ZERO access anywhere until a StaffGrant row exists for
15	 * them. This module is the only thing that ever reads StaffGrant, and it is
16	 * only ever consulted for the EMPLOYEE role — the fast path for every other
17	 * role is the existing, unchanged `canAccess` check with no DB hit.
18	 *
19	 * WHY A SEPARATE MODULE FROM lib/rbac.ts: keeps that file's existing,
20	 * heavily-relied-on exports byte-identical, so a diff against it proves this
21	 * feature couldn't have regressed anything already using it.
22	 *
23	 * LESSON APPLIED FROM lib/team-guard.ts's DELETION: that per-org permission
24	 * system was ripped out because it only ever filtered nav — no loader or
25	 * action actually checked it, so the "permission" was a promise the server
26	 * never kept. Every area opened to EMPLOYEE here is migrated at the ACTION
27	 * layer (see lib/actions-reddit-templates.ts, lib/actions-company-mail.ts,
28	 * lib/mail/imap.ts's resolveMailbox, lib/actions-support.ts's
29	 * requireTicketActor, lib/actions-chat.ts), not just its page.
30	 */
31	
32	export async function hasAreaAccess(user: Pick<User, "id" | "role">, area: Area): Promise<boolean> {
33	  if (canAccess(user.role, area)) return true;
34	  if (user.role !== "EMPLOYEE") return false;
35	  const grant = await db.staffGrant.findUnique({
36	    where: { userId_area: { userId: user.id, area } },
37	    select: { id: true },
38	  });
39	  return !!grant;
40	}
41	
42	export async function hasAnyAreaAccess(user: Pick<User, "id" | "role">, areas: Area[]): Promise<boolean> {
43	  for (const area of areas) {
44	    if (await hasAreaAccess(user, area)) return true;
45	  }
46	  return false;
47	}
48	
49	/** Server-action guard. Throws UNAUTHORIZED/FORBIDDEN — never redirects. */
50	export async function requireGrant(area: Area): Promise<User> {
51	  const user = await realUser();
52	  if (!user) throw new Error("UNAUTHORIZED");
53	  if (user.role === "CUSTOMER") throw new Error("FORBIDDEN");
54	  if (!(await hasAreaAccess(user, area))) throw new Error("FORBIDDEN");
55	  return user;
56	}
57	
58	/** Server-action guard, OR-of-areas variant (e.g. company mail listing, reachable via either grant). */
59	export async function requireAnyGrant(areas: Area[]): Promise<User> {
60	  const user = await realUser();
61	  if (!user) throw new Error("UNAUTHORIZED");
62	  if (user.role === "CUSTOMER") throw new Error("FORBIDDEN");
63	  if (!(await hasAnyAreaAccess(user, areas))) throw new Error("FORBIDDEN");
64	  return user;
65	}
66	
67	/**
68	 * Page guard — shape-compatible drop-in for lib/rbac.ts's `requireArea`, so
69	 * migrating a page file is a one-line swap. Redirects instead of throwing:
70	 * /login if signed out, /dashboard if not staff and not a granted EMPLOYEE,
71	 * /admin if staff but this specific area isn't reachable.
72	 */
73	export async function requireAreaOrGrant(area: Area): Promise<User> {
74	  const user = await realUser();
75	  if (!user) redirect("/login");
76	  if (!isStaff(user.role) && user.role !== "EMPLOYEE") redirect("/dashboard");
77	  if (!(await hasAreaAccess(user, area))) {
78	    redirect(user.role === "EMPLOYEE" ? "/staff" : "/admin");
79	  }
80	  return user;
81	}
82	
83	/** Every area an EMPLOYEE has been granted — drives the staff portal's dynamic nav and the admin grant checklist. */
84	export async function listGrantedAreas(userId: string): Promise<Area[]> {
85	  const rows = await db.staffGrant.findMany({ where: { userId }, select: { area: true } });
86	  return rows.map((r) => r.area as Area);
87	}
88	
89	/**
90	 * The fixed list of areas an admin can grant an EMPLOYEE, plus display
91	 * metadata for the grant checklist (admin/staff/StaffGrantChecklist.tsx) and
92	 * the staff portal's dynamic nav. Adding a future grantable tool is a
93	 * one-line addition here — nothing else needs to change to surface it.
94	 */
95	export const GRANTABLE_AREAS: { area: Area; label: string; href: string; hint?: string }[] = [
96	  { area: "supportTickets", label: "Support tickets", href: "/staff/support" },
97	  { area: "liveChat", label: "Live chat", href: "/staff/chat" },
98	  { area: "redditTemplates", label: "Reddit templates", href: "/staff/reddit", hint: "Static content library — no live posting, no customer data." },
99	  { area: "companyInbox", label: "Company inbox", href: "/staff/inbox", hint: "Read/send as admin@, support@, etc. — never a customer's mail." },
100	  { area: "companyMailboxes", label: "Company mailboxes", href: "/staff/mailboxes", hint: "Create/reset company addresses — no customer billing or PII." },
101	  { area: "clientsBasic", label: "Clients (limited)", href: "/staff/clients", hint: "Name, email, signup date, ticket/server counts only — no financials, IPs, or audit trail." },
102	  { area: "tasks", label: "Tasks & projects", href: "/staff/tasks" },
103	];
