1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import type { Role } from "@prisma/client";
6	import { db } from "./db";
7	import { requireAdmin } from "./auth";
8	
9	const roleSchema = z.enum(["CUSTOMER", "SUPPORT", "BILLING", "ADMIN"]);
10	
11	/**
12	 * Promote/demote a user's role. ADMIN-only, audit-logged. An admin can't
13	 * change their own role (prevents locking yourself out of admin).
14	 */
15	export async function setUserRole(
16	  userId: string,
17	  role: Role,
18	): Promise<{ ok?: boolean; error?: string }> {
19	  const admin = await requireAdmin();
20	
21	  const parsed = roleSchema.safeParse(role);
22	  if (!parsed.success) return { error: "Invalid role." };
23	
24	  if (userId === admin.id) return { error: "You can't change your own role." };
25	
26	  const target = await db.user.findUnique({ where: { id: userId } });
27	  if (!target) return { error: "User not found." };
28	  if (target.role === parsed.data) return { ok: true };
29	
30	  await db.user.update({ where: { id: userId }, data: { role: parsed.data } });
31	  await db.auditLog.create({
32	    data: {
33	      userId: admin.id,
34	      action: "staff.setRole",
35	      detail: `${target.email}: ${target.role} → ${parsed.data}`,
36	    },
37	  });
38	
39	  revalidatePath("/admin/staff");
40	  revalidatePath(`/admin/users/${userId}`);
41	  return { ok: true };
42	}
