1	import Link from "next/link";
2	import { requireArea } from "@/lib/rbac";
3	import { db } from "@/lib/db";
4	import { PageHeader, Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";
5	import { SuspendUserButton } from "@/components/AdminControls";
6	import { ImpersonateButton } from "@/components/admin/ImpersonateButton";
7	import { BulkTable, type BulkRow } from "@/components/admin/BulkTable";
8	import { bulkSuspendUsers } from "@/lib/actions-admin-billing";
9	import { paginate, pageHref } from "@/lib/pagination";
10	import { fleetMrrCents } from "@/lib/admin-metrics";
11	
12	export const dynamic = "force-dynamic";
13	
14	const PER_PAGE = 25;
15	
16	export default async function AdminUsers({
17	  searchParams,
18	}: {
19	  searchParams: Promise<{ q?: string; page?: string }>;
20	}) {
21	  // See the note on /admin/users/[id]: `clients` admits SUPPORT, but Impersonate
22	  // and Suspend are `requireAdmin()` actions. Render only what the role can use.
23	  const me = await requireArea("clients");
24	  const canAct = me.role === "ADMIN";
25	  const sp = await searchParams;
26	  const query = (sp.q ?? "").trim();
27	
28	  const where = query
29	    ? {
30	        OR: [
31	          { email: { contains: query, mode: "insensitive" as const } },
32	          { name: { contains: query, mode: "insensitive" as const } },
33	        ],
34	      }
35	    : undefined;
36	
37	  const total = await db.user.count({ where });
38	  const pg = paginate(sp, total, PER_PAGE);
39	  const users = await db.user.findMany({
40	    where,
41	    include: {
42	      servers: {
43	        where: { status: { notIn: ["DELETING"] } },
44	        select: {
45	          isFree: true,
46	          status: true,
47	          termMonths: true,
48	          plan: { select: { priceCents: true } },
49	          gamePlan: { select: { priceCents: true, termMonths: true } },
50	        },
51	      },
52	    },
53	    orderBy: { createdAt: "desc" },
54	    skip: pg.skip,
55	    take: pg.take,
56	  });
57	
58	  const exportHref = `/api/admin/export?type=users${query ? `&q=${encodeURIComponent(query)}` : ""}`;
59	
60	  const rows: BulkRow[] = users.map((u) => {
61	    const mrr = fleetMrrCents(u.servers);
62	    return {
63	      id: u.id,
64	      selectable: u.role !== "ADMIN",
65	      cells: [
66	        <span key="c">
67	          <Link
68	            href={`/admin/users/${u.id}`}
69	            className={`font-medium hover:text-brand-300 ${mrr > 0 ? "text-emerald-300" : ""}`}
70	            title={mrr > 0 ? `Paying customer — ${fmtMoney(mrr)}/mo` : undefined}
71	          >
72	            {u.name}
73	          </Link>
74	          <span className="ml-2 text-xs text-slate-500">{u.email}</span>
75	          {u.suspended && (
76	            <span className="ml-2">
77	              <Badge tone="red">suspended</Badge>
78	            </span>
79	          )}
80	        </span>,
81	        <Badge key="r" tone={u.role === "ADMIN" ? "brand" : "slate"}>{u.role.toLowerCase()}</Badge>,
82	        u.servers.length,
83	        fmtMoney(u.balanceCents),
84	        mrr > 0 ? `${fmtMoney(mrr)}/mo` : <span key="m" className="text-slate-500">—</span>,
85	        <span key="j" className="text-xs text-slate-400">{timeAgo(u.createdAt)}</span>,
86	        <div key="a" className="flex items-center justify-end gap-2">
87	          <Link href={`/admin/users/${u.id}`} className="btn-ghost py-1 text-xs">
88	            View →
89	          </Link>
90	          {canAct && u.role !== "ADMIN" && <ImpersonateButton userId={u.id} email={u.email} small />}
91	          {canAct && u.role !== "ADMIN" && <SuspendUserButton userId={u.id} suspended={u.suspended} />}
92	        </div>,
93	      ],
94	    };
95	  });
96	
97	  return (
98	    <div className="space-y-6">
99	      <PageHeader title="Clients" sub={`${total} account${total === 1 ? "" : "s"}${query ? ` matching “${query}”` : ""}`}>
100	        <form method="GET" className="flex items-center gap-2">
101	          <input
102	            className="input w-64 py-2"
103	            type="search"
104	            name="q"
105	            placeholder="Search email or name…"
106	            defaultValue={query}
107	          />
108	          <button className="btn-secondary py-2">Search</button>
109	          {query && (
110	            <Link href="/admin/users" className="btn-ghost py-2 text-xs">
111	              Clear
112	            </Link>
113	          )}
114	        </form>
115	      </PageHeader>
116	
117	      <div className="card p-0">
118	        <BulkTable
119	          columns={[
120	            { header: "Client" },
121	            { header: "Role" },
122	            { header: "Servers" },
123	            { header: "Balance" },
124	            { header: "Monthly spend" },
125	            { header: "Joined" },
126	            { header: "Actions", className: "text-right" },
127	          ]}
128	          rows={rows}
129	          exportHref={exportHref}
130	          minWidth={860}
131	          empty="No clients match this search."
132	          actions={
133	            canAct
134	              ? [
135	                  {
136	                    label: "Suspend",
137	                    danger: true,
138	                    // State the consequence, not the verb. Suspension logs the
139	                    // account out immediately and blocks sign-in; their servers
140	                    // keep running and keep costing us until someone unsuspends.
141	                    confirm:
142	                      "Suspend the selected clients?\n\nEach one is signed out immediately and cannot log back in until unsuspended. Their servers keep running and are not touched.",
143	                    run: bulkSuspendUsers,
144	                  },
145	                ]
146	              : []
147	          }
148	        />
149	
150	        <div className="flex items-center justify-between gap-3 px-5 py-4 text-xs text-slate-500">
151	          <span>
152	            Page {pg.page} of {pg.pages} · {total} client{total === 1 ? "" : "s"}
153	          </span>
154	          <div className="flex items-center gap-2">
155	            {pg.page > 1 && (
156	              <Link href={pageHref("/admin/users", { q: query }, pg.page - 1)} className="btn-ghost py-1 text-xs">
157	                ← Prev
158	              </Link>
159	            )}
160	            {pg.page < pg.pages && (
161	              <Link href={pageHref("/admin/users", { q: query }, pg.page + 1)} className="btn-ghost py-1 text-xs">
162	                Next →
163	              </Link>
164	            )}
165	          </div>
166	        </div>
167	      </div>
168	
169	      <p className="text-xs text-slate-500">
170	        Wallet credits are issued from a client&apos;s profile page. Monthly spend is the committed MRR of the
171	        client&apos;s active paid servers. Select rows to bulk-suspend or export the filtered set to CSV.
172	      </p>
173	    </div>
174	  );
175	}
