229	export function firewallPortLabel(rule: {
230	  protocol: string;
231	  portFrom: number | null;
232	  portTo: number | null;
233	}): string {
234	  if (rule.protocol === "ICMP" || rule.protocol === "ALL") return "—";
235	  if (rule.portFrom == null && rule.portTo == null) return "all";
236	  if (rule.portFrom === rule.portTo) return String(rule.portFrom);
237	  return `${rule.portFrom}–${rule.portTo}`;
238	}
