/**
 * Does `pathname` belong to `href`? Exact match, or a detail route beneath it
 * (`/admin/users/123`). The bare "/admin" only ever matches exactly so it can
 * never swallow every deeper route.
 */
export function hrefMatches(href: string, pathname: string): boolean {
  if (pathname === href) return true;
  if (href === "/admin") return false;
  return pathname.startsWith(href + "/");
}

