"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireAdmin } from "./auth";
import { requireAnyGrant } from "./staff-grants";

const PATH = "/admin/canned-replies";

// Same access model as the tools these snippets are used from: a granted
// EMPLOYEE reads/writes exactly like existing SUPPORT/ADMIN staff, via
// requireAnyGrant's canAccess() fast path — no separate area of its own.
const REPLY_AREAS = ["supportTickets", "liveChat"] as const;

export type CannedReplyItem = {
  id: string;
  title: string;
  body: string;
  createdAt: string;
  updatedAt: string;
  createdBy: { name: string; email: string } | null;
};

export async function listCannedReplies(): Promise<CannedReplyItem[]> {
  await requireAnyGrant([...REPLY_AREAS]);
  const rows = await db.cannedReply.findMany({
    orderBy: { title: "asc" },
    include: { createdBy: { select: { name: true, email: true } } },
  });
  return rows.map((r) => ({
    id: r.id,
    title: r.title,
    body: r.body,
    createdAt: r.createdAt.toISOString(),
    updatedAt: r.updatedAt.toISOString(),
    createdBy: r.createdBy ? { name: r.createdBy.name, email: r.createdBy.email } : null,
  }));
}

export async function createCannedReply(title: string, body: string): Promise<{ id?: string; error?: string }> {
  const user = await requireAnyGrant([...REPLY_AREAS]);
  const cleanTitle = String(title ?? "").trim().slice(0, 120);
  const cleanBody = String(body ?? "").trim();
  if (!cleanTitle) return { error: "Enter a title." };
  if (!cleanBody) return { error: "Enter the reply text." };
  if (cleanBody.length > 5000) return { error: "Reply is too long (5000 char max)." };

  const reply = await db.cannedReply.create({
    data: { title: cleanTitle, body: cleanBody, createdById: user.id },
  });
  revalidatePath(PATH);
  return { id: reply.id };
}

export async function updateCannedReply(id: string, title: string, body: string): Promise<{ error?: string }> {
  await requireAnyGrant([...REPLY_AREAS]);
  const cleanTitle = String(title ?? "").trim().slice(0, 120);
  const cleanBody = String(body ?? "").trim();
  if (!cleanTitle) return { error: "Enter a title." };
  if (!cleanBody) return { error: "Enter the reply text." };
  if (cleanBody.length > 5000) return { error: "Reply is too long (5000 char max)." };

  await db.cannedReply
    .update({ where: { id }, data: { title: cleanTitle, body: cleanBody } })
    .catch(() => undefined);
  revalidatePath(PATH);
  return {};
}

/**
 * Delete stays ADMIN-only rather than following create/edit's grant gate —
 * a shared snippet library is low-stakes either way, but a support agent
 * wiping a reply teammates rely on (by accident or after a dispute) is a
 * worse failure mode than one they didn't author sitting around unused.
 * Picking the safer default since nothing forces this choice either way.
 */
export async function deleteCannedReply(id: string): Promise<void> {
  await requireAdmin();
  await db.cannedReply.delete({ where: { id } }).catch(() => undefined);
  revalidatePath(PATH);
}

"use client";

import { useState, useTransition } from "react";
import type { Area } from "@/lib/rbac";
import { setStaffGrant } from "@/lib/actions-staff";

export type GrantableArea = { area: Area; label: string; href: string; hint?: string };

/**
 * One checkbox per lib/staff-grants.ts's GRANTABLE_AREAS — the owner hand-picks
 * exactly which tools this employee can reach. Optimistic toggle (matches
 * StaffRoleControls' pattern elsewhere in this file's sibling component): the
 * checkbox flips immediately and reverts only if the server actually refuses,
 * so a reviewer clicking through a dozen boxes isn't waiting on each one.
 */
export function StaffGrantChecklist({
  userId,
  areas,
  granted,
}: {
  userId: string;
  areas: GrantableArea[];
  granted: Area[];
}) {
  const [grantedSet, setGrantedSet] = useState<Set<Area>>(new Set(granted));
  const [pendingArea, setPendingArea] = useState<Area | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [, startTransition] = useTransition();

  function toggle(area: Area, next: boolean) {
    setError(null);
    setPendingArea(area);
    setGrantedSet((prev) => {
      const copy = new Set(prev);
      if (next) copy.add(area);
      else copy.delete(area);
      return copy;
    });
    startTransition(async () => {
      const res = await setStaffGrant(userId, area, next);
      setPendingArea(null);
      if (res.error) {
        setError(res.error);
        // The checkbox must never show a grant that isn't real server-side.
        setGrantedSet((prev) => {
          const copy = new Set(prev);
          if (next) copy.delete(area);
          else copy.add(area);
          return copy;
        });
      }
    });
  }

  return (
    <div className="space-y-2">
      {areas.map((a) => {
        const checked = grantedSet.has(a.area);
        return (
          <label
            key={a.area}
            className="flex cursor-pointer items-start gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] p-3 hover:border-white/[0.12]"
          >
            <input
              type="checkbox"
              className="mt-0.5"
              checked={checked}
              disabled={pendingArea === a.area}
              onChange={(e) => toggle(a.area, e.target.checked)}
            />
            <span className="min-w-0">
              <span className="block text-sm font-medium text-slate-200">{a.label}</span>
              {a.hint && <span className="block text-xs text-slate-500">{a.hint}</span>}
            </span>
          </label>
        );
      })}
      {error && <p className="text-xs text-red-400">{error}</p>}
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { addStaffIp, removeStaffIp } from "@/lib/actions-staff";

export type StaffIpRow = { id: string; cidr: string; label: string | null; createdAt: string };

/**
 * Add/remove rows for one employee's StaffIpAllow list. Deliberately a plain
 * row list, not a comma-string editor — matches the schema's own reasoning
 * (prisma/schema.prisma's StaffIpAllow comment) for why this is per-row here
 * unlike the rarely-touched global `allowed_admin_ips` setting.
 */
export function StaffIpAllowlist({ userId, rows }: { userId: string; rows: StaffIpRow[] }) {
  const [cidr, setCidr] = useState("");
  const [label, setLabel] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [adding, startAdd] = useTransition();
  const [removingId, setRemovingId] = useState<string | null>(null);
  const [, startRemove] = useTransition();

  function add() {
    setError(null);
    startAdd(async () => {
      const res = await addStaffIp(userId, cidr, label || undefined);
      if (res.error) {
        setError(res.error);
        return;
      }
      setCidr("");
      setLabel("");
    });
  }

  function remove(id: string) {
    setRemovingId(id);
    startRemove(async () => {
      await removeStaffIp(userId, id);
      setRemovingId(null);
    });
  }

  return (
    <div className="space-y-3">
      {rows.length === 0 ? (
        <p className="text-xs text-slate-500">
          No IPs configured — this employee can sign in to the staff portal from anywhere. Add one to restrict them.
        </p>
      ) : (
        <ul className="space-y-1.5">
          {rows.map((r) => (
            <li
              key={r.id}
              className="flex items-center justify-between gap-3 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2"
            >
              <span className="font-mono text-xs text-slate-200">
                {r.cidr}
                {r.label && <span className="ml-2 font-sans text-slate-500">{r.label}</span>}
              </span>
              <button
                className="text-xs text-red-400 hover:underline disabled:opacity-50"
                disabled={removingId === r.id}
                onClick={() => remove(r.id)}
              >
                {removingId === r.id ? "removing…" : "Remove"}
              </button>
            </li>
          ))}
        </ul>
      )}

      <div className="flex flex-wrap items-center gap-2">
        <input
          className="input w-44 py-1.5 text-xs font-mono"
          placeholder="203.0.113.4 or /24"
          value={cidr}
          onChange={(e) => setCidr(e.target.value)}
          disabled={adding}
        />
        <input
          className="input w-40 py-1.5 text-xs"
          placeholder="Label (optional)"
          value={label}
          onChange={(e) => setLabel(e.target.value)}
          disabled={adding}
        />
        <button className="btn-secondary py-1.5 text-xs" disabled={adding || !cidr.trim()} onClick={add}>
          {adding ? "Adding…" : "Add"}
        </button>
      </div>
      {error && <p className="text-xs text-red-400">{error}</p>}
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { createEmployee } from "@/lib/actions-staff";

/**
 * Creates a Role.EMPLOYEE account with zero access — grants are handed out
 * afterwards from the new employee's detail page. The temp password is shown
 * ONCE (this response is the only place it exists in plaintext, matching
 * prisma/seed.ts's admin-account bootstrap) so the admin can copy it before
 * navigating away.
 */
export function CreateEmployeeForm() {
  const [email, setEmail] = useState("");
  const [name, setName] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [created, setCreated] = useState<{ email: string; tempPassword: string } | null>(null);
  const [pending, start] = useTransition();

  function submit() {
    setError(null);
    setCreated(null);
    const submittedEmail = email.trim();
    start(async () => {
      const res = await createEmployee(submittedEmail, name);
      if (!res.ok) {
        setError(res.error);
        return;
      }
      setCreated({ email: submittedEmail, tempPassword: res.tempPassword });
      setEmail("");
      setName("");
    });
  }

  return (
    <div className="card space-y-3 p-4">
      <h2 className="font-semibold">New employee</h2>
      <p className="text-xs text-slate-500">
        Creates a limited-access account with no tools granted yet — pick exactly what they can use from their
        detail page after creating them.
      </p>
      <div className="flex flex-wrap items-center gap-2">
        <input
          className="input w-56 py-1.5 text-sm"
          placeholder="Email"
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          disabled={pending}
        />
        <input
          className="input w-48 py-1.5 text-sm"
          placeholder="Full name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          disabled={pending}
        />
        <button
          className="btn-secondary py-1.5 text-sm"
          disabled={pending || !email.trim() || !name.trim()}
          onClick={submit}
        >
          {pending ? "Creating…" : "Create employee"}
        </button>
      </div>
      {error && <p className="text-xs text-red-400">{error}</p>}
      {created && (
        <p className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 p-3 text-xs text-emerald-200">
          {created.email} created. Temporary password (shown once — copy it now):{" "}
          <span className="font-mono font-semibold">{created.tempPassword}</span>
        </p>
      )}
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { requireArea } from "@/lib/rbac";
import type { Area } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, Badge, timeAgo } from "@/components/ui/primitives";
import { StaffGrantChecklist } from "@/components/admin/StaffGrantChecklist";
import { StaffIpAllowlist } from "@/components/admin/StaffIpAllowlist";
import { GRANTABLE_AREAS } from "@/lib/staff-grants";

export const dynamic = "force-dynamic";

const roleTone: Record<string, "brand" | "green" | "amber" | "slate"> = {
  ADMIN: "brand",
  SUPPORT: "green",
  BILLING: "amber",
  EMPLOYEE: "slate",
};

export default async function AdminStaffDetail({ params }: { params: Promise<{ id: string }> }) {
  // Staff management stays platform/ADMIN-only forever — this is the tool that
  // GRANTS access to everything else, so it must never itself be delegable via
  // a StaffGrant. requireArea (lib/rbac.ts), not requireGrant/requireAreaOrGrant
  // (lib/staff-grants.ts), is the whole point.
  await requireArea("platform");
  const { id } = await params;

  const user = await db.user.findUnique({
    where: { id },
    include: {
      staffGrants: { orderBy: { area: "asc" } },
      staffIpAllows: { orderBy: { createdAt: "asc" } },
    },
  });
  if (!user || user.role === "CUSTOMER") notFound();

  const isEmployee = user.role === "EMPLOYEE";
  const grantedAreas = user.staffGrants.map((g) => g.area as Area);

  return (
    <div className="space-y-6">
      <PageHeader title={user.name} sub={`${user.email} · joined ${timeAgo(user.createdAt)}`}>
        <Badge tone={roleTone[user.role] ?? "slate"}>{user.role.toLowerCase()}</Badge>
        {user.suspended && <Badge tone="red">suspended</Badge>}
        <Link href={`/admin/audit?staff=${user.id}`} className="btn-ghost py-1.5 text-xs">
          View activity →
        </Link>
        <Link href="/admin/staff" className="btn-ghost py-1.5 text-xs">
          ← All staff
        </Link>
      </PageHeader>

      <div className="card p-5">
        <h2 className="mb-1 font-semibold">Tool access</h2>
        {isEmployee ? (
          <>
            <p className="mb-3 text-xs text-slate-500">
              Hand-picked, not a fixed role — nothing is reachable until checked here, and every one of these is
              re-enforced at the action layer, not just hidden from the nav (see lib/staff-grants.ts).
            </p>
            <StaffGrantChecklist userId={user.id} areas={GRANTABLE_AREAS} granted={grantedAreas} />
          </>
        ) : (
          <p className="text-xs text-slate-500">
            {user.role.toLowerCase()} reaches every area its role allows (see the legend on the staff list) —
            hand-picked grants only apply to limited-access employee accounts.
          </p>
        )}
      </div>

      <div className="card p-5">
        <h2 className="mb-1 font-semibold">IP allowlist</h2>
        {isEmployee ? (
          <>
            <p className="mb-3 text-xs text-slate-500">
              Restrict which networks this employee can sign in to the staff portal from. Empty = sign in from
              anywhere; the moment one row exists, every other network is refused for this employee only.
            </p>
            <StaffIpAllowlist
              userId={user.id}
              rows={user.staffIpAllows.map((r) => ({
                id: r.id,
                cidr: r.cidr,
                label: r.label,
                createdAt: r.createdAt.toISOString(),
              }))}
            />
          </>
        ) : (
          <p className="text-xs text-slate-500">
            {user.role.toLowerCase()} accounts sign in through the admin console, which has its own global IP
            allowlist (Settings) — a per-account list here only applies to limited-access employee accounts.
          </p>
        )}
      </div>
    </div>
  );
}

import { redirect } from "next/navigation";
import { realUser } from "@/lib/auth";
import { hasAnyAreaAccess } from "@/lib/staff-grants";
import { listCannedReplies } from "@/lib/actions-canned-replies";
import { PageHeader } from "@/components/ui/primitives";
import { CannedReplyManager } from "./CannedReplyManager";

export const dynamic = "force-dynamic";

/**
 * Same OR-of-areas the actions in lib/actions-canned-replies.ts enforce
 * (requireAnyGrant(["supportTickets","liveChat"])) — a BILLING agent who
 * reaches /admin (app/admin/layout.tsx already refused a CUSTOMER or
 * unauthenticated request before this file ever runs) still has no reason to
 * see this page, so it redirects them back rather than rendering an empty
 * snippet library they can't use.
 */
async function requireCannedReplyAccess() {
  const user = await realUser();
  if (!user) redirect("/login");
  if (!(await hasAnyAreaAccess(user, ["supportTickets", "liveChat"]))) redirect("/admin");
  return user;
}

export default async function AdminCannedReplies() {
  await requireCannedReplyAccess();
  const replies = await listCannedReplies();

  return (
    <div className="space-y-6">
      <PageHeader
        title="Quick replies"
        sub={`${replies.length} snippet${replies.length === 1 ? "" : "s"} · shared across tickets and live chat`}
      />
      <CannedReplyManager replies={replies} />
    </div>
  );
}

