"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  createCannedReply,
  updateCannedReply,
  deleteCannedReply,
  type CannedReplyItem,
} from "@/lib/actions-canned-replies";
import { timeAgo } from "@/components/ui/primitives";

/**
 * List + create + edit + delete for the CannedReply snippet library. Delete is
 * only rendered for ADMIN (`canDelete`) — create/edit are already refused
 * server-side for anyone without supportTickets/liveChat, so no client-side
 * gate is needed for those; `canDelete` exists purely to avoid rendering a
 * button the server would refuse (same reasoning as app/admin/users/[id]'s
 * `canAct` split).
 */
export function CannedReplyManager({
  replies,
  canDelete,
}: {
  replies: CannedReplyItem[];
  canDelete: boolean;
}) {
  const router = useRouter();
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [creating, startCreate] = useTransition();

  function create() {
    setError(null);
    startCreate(async () => {
      const res = await createCannedReply(title, body);
      if (res.error) {
        setError(res.error);
        return;
      }
      setTitle("");
      setBody("");
      router.refresh();
    });
  }

  return (
    <div className="space-y-4">
      <div className="card space-y-3 p-4">
        <h2 className="font-semibold">New reply</h2>
        <input
          className="input w-full py-1.5 text-sm"
          placeholder="Title (e.g. \"Refund policy\")"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          disabled={creating}
          maxLength={120}
        />
        <textarea
          className="input min-h-24 w-full text-sm"
          placeholder="Reply text…"
          value={body}
          onChange={(e) => setBody(e.target.value)}
          disabled={creating}
          maxLength={5000}
        />
        <div className="flex items-center gap-3">
          <button
            className="btn-secondary py-1.5 text-sm"
            disabled={creating || !title.trim() || !body.trim()}
            onClick={create}
          >
            {creating ? "Saving…" : "Add reply"}
          </button>
          {error && <span className="text-xs text-red-400">{error}</span>}
        </div>
      </div>

      {replies.length === 0 ? (
        <p className="card p-8 text-center text-sm text-slate-500">
          No quick replies yet — add one above to seed the library.
        </p>
      ) : (
        <ul className="space-y-3">
          {replies.map((r) => (
            <ReplyRow key={r.id} reply={r} canDelete={canDelete} />
          ))}
        </ul>
      )}
    </div>
  );
}

function ReplyRow({ reply, canDelete }: { reply: CannedReplyItem; canDelete: boolean }) {
  const router = useRouter();
  const [editing, setEditing] = useState(false);
  const [title, setTitle] = useState(reply.title);
  const [body, setBody] = useState(reply.body);
  const [error, setError] = useState<string | null>(null);
  const [saving, startSave] = useTransition();
  const [deleting, startDelete] = useTransition();
  const edited = new Date(reply.updatedAt).getTime() - new Date(reply.createdAt).getTime() > 1000;

  function save() {
    setError(null);
    startSave(async () => {
      const res = await updateCannedReply(reply.id, title, body);
      if (res.error) {
        setError(res.error);
        return;
      }
      setEditing(false);
      router.refresh();
    });
  }

  return (
    <li className="card p-4">
      {editing ? (
        <div className="space-y-2">
          <input
            className="input w-full py-1.5 text-sm"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            disabled={saving}
            maxLength={120}
          />
          <textarea
            className="input min-h-24 w-full text-sm"
            value={body}
            onChange={(e) => setBody(e.target.value)}
            disabled={saving}
            maxLength={5000}
          />
          <div className="flex items-center gap-3">
            <button className="btn-secondary py-1 text-xs" disabled={saving} onClick={save}>
              {saving ? "Saving…" : "Save"}
            </button>
            <button
              type="button"
              className="btn-ghost py-1 text-xs"
              onClick={() => {
                setTitle(reply.title);
                setBody(reply.body);
                setEditing(false);
                setError(null);
              }}
            >
              Cancel
            </button>
            {error && <span className="text-xs text-red-400">{error}</span>}
          </div>
        </div>
      ) : (
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <p className="font-medium text-slate-200">{reply.title}</p>
            <p className="mt-1 whitespace-pre-wrap break-words text-sm text-slate-400">{reply.body}</p>
            <p className="mt-2 text-xs text-slate-500">
              {reply.createdBy?.name ?? "unknown"} · {timeAgo(new Date(reply.createdAt))}
              {edited ? " · edited" : ""}
            </p>
          </div>
          <div className="flex shrink-0 gap-1">
            <button className="btn-ghost py-1 text-xs" onClick={() => setEditing(true)}>
              Edit
            </button>
            {canDelete && (
              <button
                className="btn-ghost py-1 text-xs text-red-400"
                disabled={deleting}
                onClick={() => {
                  if (window.confirm("Delete this quick reply?")) {
                    startDelete(async () => {
                      await deleteCannedReply(reply.id);
                      router.refresh();
                    });
                  }
                }}
              >
                {deleting ? "…" : "Delete"}
              </button>
            )}
          </div>
        </div>
      )}
    </li>
  );
}

