/* ================================================================== *
 * THE HAZARD CLASS ITSELF: every export of a "use server" module is a
 * network-callable endpoint
 *
 * This codebase has been bitten by this twice. `verifyTotpForUser` lived in
 * lib/actions-2fa.ts, so it was a registered action taking a caller-supplied
 * userId with no session check, no ownership check and no rate limit, returning
 * a raw boolean and spending a backup code — an unauthenticated 2FA
 * brute-force oracle against any named account, reachable without logging in and
 * bypassing login()'s throttle entirely. `safeNext` had to be moved out of
 * lib/actions.ts for the same reason.
 *
 * Both were fixed by moving ONE function. Neither fix stopped it happening to
 * the next function, because nothing checked. These tests check — across every
 * "use server" module in lib/, on every export, every run.
 * ================================================================== */

import { readdirSync } from "node:fs";

/** Every lib/**\/*.ts whose FIRST statement is the "use server" directive. */
function useServerModules(): string[] {
  const out: string[] = [];
  const walk = (dir: string, prefix: string) => {
    for (const entry of readdirSync(new URL(dir, import.meta.url), { withFileTypes: true })) {
      if (entry.isDirectory()) walk(`${dir}${entry.name}/`, `${prefix}${entry.name}/`);
      else if (entry.name.endsWith(".ts")) {
        let src: string;
        try {
          src = readFileSync(new URL(`${dir}${entry.name}`, import.meta.url), "utf8");
        } catch {
          continue; // a sibling edit removed it mid-run
        }
        const first = src.split("\n").find((l) => l.trim() !== "");
        if (first && /^["']use server["']/.test(first.trim())) out.push(`${prefix}${entry.name}`);
      }
    }
  };
  walk("../lib/", "lib/");
  return out.sort();
}

type Export = { name: string; line: number; isAsync: boolean; body: string };

/** Top-level exported values in a module, with the body that follows each. */
function exportsOf(src: string): Export[] {
  const lines = src.split("\n");
  const found: Export[] = [];
  for (let i = 0; i < lines.length; i++) {
    const fn = /^export\s+(async\s+)?function\s+([A-Za-z0-9_]+)/.exec(lines[i]);
    const cn = /^export\s+const\s+([A-Za-z0-9_]+)\s*(?::[^=]*)?=\s*(async\s*)?/.exec(lines[i]);
    if (!fn && !cn) continue;
    const name = fn ? fn[2] : cn![1];
    const isAsync = fn ? Boolean(fn[1]) : Boolean(cn![2]);
    // The body ends at the first line that is NOTHING BUT a closing brace.
    // Not "starts with }": a multi-line return type closes as `}> {` and a
    // multi-line object parameter as `}): Promise<...> {`, both at column 0, and
    // that shape cut four genuinely-guarded actions off above their own guard
    // and reported them as unauthenticated. A tripwire that cries wolf gets muted.
    let body = "";
    for (let j = i; j < lines.length; j++) {
      body += lines[j] + "\n";
      if (j > i && /^[}\]]\s*;?\s*$/.test(lines[j])) break;
    }
    found.push({ name, line: i + 1, isAsync, body });
  }
  return found;
}

/**
 * Tokens that establish WHO is calling, inside the function itself.
 *
 * `requireUser`/`requireAdmin`/`requireStaff`/`requireArea`/`realUser` are the
 * primitives; `ownedX`/`resolveX`/`assertX` are the per-module helpers that wrap
 * them and additionally prove the caller owns the row named by a client-supplied
 * id. A guard in the CALLER does not count and is not detectable here — that is
 * the point, since the caller of a server action is the network.
 */
const GUARD =
  /\b(requireUser|requireAdmin|requireStaff|requireArea|realUser|currentUser|assertNotImpersonating)\s*\(|\b(owned|resolve|assert|require)[A-Z][A-Za-z0-9_]*\s*\(/;

/**
 * Exports that are SUPPOSED to be callable by an anonymous stranger, each with
 * the reason. Anything not here and not guarded is a finding, not a style note.
 *
 * Adding a name here is a security decision. It says: this endpoint is reachable
 * by anyone on the internet with no session, and that is correct.
 */
const ANONYMOUS_BY_DESIGN: Record<string, string> = {
  // The front door — these exist to be called before you have a session.
  "lib/actions.ts:register": "signup",
  "lib/actions.ts:login": "sign-in",
  "lib/actions.ts:logout": "clears cookies only",
  "lib/actions-account.ts:requestPasswordReset":
    "reset request; throttled, and answers identically whether or not the address exists",
  "lib/actions-account.ts:resetPassword":
    "redeems a 256-bit single-use token; the token IS the authentication",
  "lib/actions-account.ts:stopImpersonating": "deletes a cookie; nothing to authorise",
  "lib/actions-newsletter.ts:subscribe": "public marketing form",
  "lib/actions-contact.ts:submitContact":
    "public /contact form — prospects with no account must be able to send it; " +
    "rate-limited per attested IP + email and honeypot-guarded",
  // Pure/derived values that read nothing about anybody.
  "lib/actions-domains-dns.ts:parseDnsImport": "pure text parser, touches no data",
  "lib/actions-volumes.ts:volumePriceCents": "public price from Settings, same for everyone",
};

test("HAZARD: every export of a \"use server\" module is authenticated, or explicitly anonymous", () => {
  const modules = useServerModules();
  assert.ok(modules.length > 40, `expected the action modules, found ${modules.length}`);

  const findings: string[] = [];
  for (const rel of modules) {
    const src = code(`../${rel}`);
    const all = exportsOf(src);
    // An export may delegate to another export in the SAME file that is itself
    // guarded (resendVerificationAction -> resendVerificationEmail,
    // importDnsRecords -> addDnsRecordsBulk). That is a real guard, one hop away.
    const guardedHere = new Set(all.filter((e) => GUARD.test(e.body)).map((e) => e.name));
    for (const e of all) {
      const id = `${rel}:${e.name}`;
      if (id in ANONYMOUS_BY_DESIGN) continue;
      if (GUARD.test(e.body)) continue;
      const delegates = [...guardedHere].some((g) =>
        new RegExp(`\\b${g}\\s*\\(`).test(e.body.slice(e.body.indexOf("{"))),
      );
      if (delegates) continue;
      findings.push(`${rel}:${e.line} ${e.name}`);
    }
  }

  assert.deepEqual(
    findings,
    [],
    "These are NETWORK-CALLABLE ENDPOINTS with no session check inside them.\n" +
      "Every export of a file whose first line is \"use server\" gets a registered\n" +
      "action id that anyone can POST to, with arguments of their choosing, with no\n" +
      "session. A check in the page that renders the form is not a check.\n" +
      "Either add a guard INSIDE the function (requireUser / requireAdmin /\n" +
      "requireArea / an ownedX helper that proves the caller owns the id), or move\n" +
      "the function to a plain module, or — if it is genuinely meant to be public —\n" +
      "add it to ANONYMOUS_BY_DESIGN above with the reason.\n" +
      "Unguarded:\n  " + findings.join("\n  "),
  );
});

